"""This file contains the AgilityHeadSim class for low level interactions with
the Agility Head Simulator test tool"""

import logging
from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
import interops.libraries.desktop.decorators as deco
import interops.libraries.integrity.agility_head_sim_objects as agility_head_sim_objects
import squishtest3 as sq


logger = logging.getLogger(__name__)

class AgilityHeadSim(BaseUIPageObject):
    """
    Class for the Agility Head Simulator.
    Used to simulate fitting the HDRE Applicator to deliver electron beams.
    """

    application_name = "AgilityHeadSim"

    @deco.app_ctx_function()
    def ready(self):
        self.accessories_tab = sq.waitForObjectExists(agility_head_sim_objects.agility_Head_Simulator_Accessories_TabItem)
        self.not_fitted_radiobtn = sq.waitForObjectExists(agility_head_sim_objects.accessories_Not_Fitted_RadioButton)
        self.fixed_applr_radiobtn = sq.waitForObjectExists(agility_head_sim_objects.accessories_Fixed_Applicator_RadioButton)
        self.fixed_applr_combobox = sq.waitForObjectExists(agility_head_sim_objects.accessories_ComboBox)
        self.apply_btn = sq.waitForObjectExists(agility_head_sim_objects.accessories_Apply_Button)
        return True

    @deco.app_ctx_function()
    def select_accessories_tab(self):
        sq.mouseClick(sq.waitForObject(agility_head_sim_objects.agility_Head_Simulator_Accessories_TabItem))

    @deco.app_ctx_function()
    def set_fixed_applicator_type(self, head_type="HDRE", fitment_num='0'):
        sq.mouseClick(sq.waitForObject(agility_head_sim_objects.accessories_Fixed_Applicator_RadioButton))
        sq.snooze(2)
        sq.expand(sq.waitForObject(agility_head_sim_objects.accessories_ComboBox))
        sq.snooze(2)
        sq.mouseClick(sq.waitForObjectItem(agility_head_sim_objects.accessories_ComboBox, head_type))
        sq.snooze(2)
        # All applicator heads other than HDRE and Tubular require the fitment to be set
        if ((head_type != "HDRE") and ("Tubular" not in head_type)):
            sq.mouseClick(sq.waitForObject(agility_head_sim_objects.accessories_fitment_Edit))
            sq.snooze(2)
            sq.nativeType("<Backspace>")
            sq.nativeType("<Backspace>")
            sq.type(sq.waitForObject(agility_head_sim_objects.accessories_fitment_Edit), fitment_num)
            sq.snooze(2)
        sq.clickButton(sq.waitForObject(agility_head_sim_objects.accessories_Apply_Button))

    @deco.app_ctx_function()
    def set_applicator_not_fitted(self):
        sq.mouseClick(sq.waitForObject(agility_head_sim_objects.accessories_Not_Fitted_RadioButton))
        sq.snooze(2)
        sq.clickButton(sq.waitForObject(agility_head_sim_objects.accessories_Apply_Button))

    @deco.app_ctx_function()
    def remove_electron_applicator(self, icom_obj):
        try:
            # Note: iCom returns seven "" spaces when the Vx tag value is empty/ blank. To determine
            # if the Vx Electron Applicator has been applied, check against "       "
            if str(icom_obj.get_Vx_electron_applicator_value()) != "       ":
                logger.info("Applicator is currently fitted. Removing applicator ...") #type:ignore
                self.ready()
                self.select_accessories_tab()
                self.set_applicator_not_fitted()
                return True
            else:
                return False
        except Exception as e:
            logger.exception("remove_electron_applicator(): Error removing electron applicator: " + str(e)) #type:ignore
            logger.exception("remove_electron_applicator(): Error removing electron applicator: " + str(e))
